alter table public.urws_cases add column if not exists restricted boolean not null default false;
create table if not exists public.urws_restricted_case_links(id uuid primary key default gen_random_uuid(),tenant_id uuid,urws_case_id uuid not null references public.urws_cases(id) on delete cascade,safeguarding_case_id uuid not null references public.safeguarding_cases(id) on delete cascade,created_at timestamptz not null default now(),unique(urws_case_id,safeguarding_case_id));
alter table public.urws_restricted_case_links enable row level security;
drop policy if exists urws_restricted_links_superuser on public.urws_restricted_case_links; create policy urws_restricted_links_superuser on public.urws_restricted_case_links for all to authenticated using(app.is_superuser()) with check(app.is_superuser());
create or replace function app.urws_safeguarding_case_event_trigger() returns trigger language plpgsql security definer set search_path=public,app as $$ begin if tg_op='UPDATE' and new.status is not distinct from old.status and new.severity is not distinct from old.severity then return new; end if; insert into public.platform_event_outbox(tenant_id,event_type,aggregate_type,aggregate_id,payload,occurred_at,status) values(new.tenant_id,'safeguarding.referral','safeguarding_case',new.id,jsonb_build_object('safeguarding_case_id',new.id,'subject_person_id',new.subject_person_id,'severity',new.severity,'restricted',true),now(),'pending'); return new; end; $$;
drop trigger if exists urws_safeguarding_case_event on public.safeguarding_cases; create trigger urws_safeguarding_case_event after insert or update of status,severity on public.safeguarding_cases for each row execute function app.urws_safeguarding_case_event_trigger();
insert into public.urws_event_rules(organization_id,event_type,case_type_code,subject_type,priority,public_summary_template,origin_prefix,auto_open,active,conditions,metadata) values(null,'safeguarding.referral','safeguarding_referral','safeguarding_case','critical','Restricted safeguarding referral requires authorized review.','safeguarding-referral',true,true,'{}'::jsonb,'{"restricted":true,"never_copy_details":true}'::jsonb) on conflict (organization_id,event_type,case_type_code) do update set active=true,auto_open=true,priority='critical',metadata=excluded.metadata;